export interface ColumnShape {
  name: string;
  kind: "integer" | "text";
  primary: boolean;
  autoIncrement: boolean;
  unique: boolean;
  nullable: boolean;
}

export interface TableShape {
  name: string;
  columns: ColumnShape[];
}

function copyCatalog(catalog: readonly TableShape[]): TableShape[] {
  return catalog.map(table => ({
    name: table.name,
    columns: table.columns.map(column => ({ ...column }))
  }));
}

export function installAuditTable(catalog: readonly TableShape[]): TableShape[] {
  if (catalog.some(table => table.name === "audit_log")) {
    throw new Error("audit_log already exists");
  }
  const result = copyCatalog(catalog);
  result.push({
    name: "audit_log",
    columns: [
      { name: "sequence", kind: "integer", primary: true, autoIncrement: true, unique: false, nullable: false },
      { name: "actor", kind: "text", primary: false, autoIncrement: false, unique: false, nullable: false },
      { name: "action", kind: "text", primary: false, autoIncrement: false, unique: false, nullable: false },
      { name: "checksum", kind: "text", primary: false, autoIncrement: false, unique: true, nullable: true }
    ]
  });
  return result;
}

export function removeAuditTable(catalog: readonly TableShape[]): TableShape[] {
  return copyCatalog(catalog.filter(table => table.name !== "audit_log"));
}
```

