import { installAuditTable, removeAuditTable } from './solution';
import type { TableShape } from './solution';

function ok(value: boolean, message: string): void {
  if (!value) throw new Error(message);
}

function equal<T>(actual: T, expected: T, message: string): void {
  if (actual !== expected) throw new Error(`${message}: expected ${String(expected)}, got ${String(actual)}`);
}

function throwsError(fn: () => void, message: string): void {
  try {
    fn();
  } catch (error) {
    if (error instanceof Error) return;
    throw new Error(`${message}: non-Error thrown`);
  }
  throw new Error(`${message}: did not throw`);
}

const catalog: TableShape[] = [{
  name: 'users',
  columns: [{
    name: 'id', kind: 'integer', primary: true, autoIncrement: false, unique: true, nullable: false
  }]
}];
const original = JSON.stringify(catalog);
const installed = installAuditTable(catalog);
equal(JSON.stringify(catalog), original, 'install must not mutate caller catalog');
equal(installed.length, 2, 'audit table is appended');
equal(installed[0].name, 'users', 'existing order is preserved');
equal(JSON.stringify(installed[1]), JSON.stringify({
  name: 'audit_log',
  columns: [
    { name: 'sequence', kind: 'integer', primary: true, autoIncrement: true, unique: false, nullable: false },
    { name: 'actor', kind: 'text', primary: false, autoIncrement: false, unique: false, nullable: false },
    { name: 'action', kind: 'text', primary: false, autoIncrement: false, unique: false, nullable: false },
    { name: 'checksum', kind: 'text', primary: false, autoIncrement: false, unique: true, nullable: false }
  ]
}), 'installed audit table has the exact required columns and flags');

installed[0].name = 'changed';
installed[0].columns[0].name = 'changed-column';
equal(JSON.stringify(catalog), original, 'installed result deeply copies existing tables and columns');
catalog[0].name = 'caller-change';
catalog[0].columns[0].unique = false;
equal(installed[0].name, 'changed', 'result does not retain caller table');
equal(installed[0].columns[0].unique, true, 'result does not retain caller column');

const sourceWithAudit: TableShape[] = [
  { name: 'before', columns: [] },
  { name: 'audit_log', columns: [{ name: 'legacy', kind: 'text', primary: false, autoIncrement: false, unique: false, nullable: true }] },
  { name: 'after', columns: [] }
];
const sourceBeforeRemoval = JSON.stringify(sourceWithAudit);
const removed = removeAuditTable(sourceWithAudit);
equal(JSON.stringify(sourceWithAudit), sourceBeforeRemoval, 'remove must not mutate caller catalog');
equal(removed.map(table => table.name).join(','), 'before,after', 'remove deletes audit table and preserves remaining order');
removed[0].name = 'mutated';
equal(sourceWithAudit[0].name, 'before', 'remove result tables are fresh');

const withoutAudit: TableShape[] = [{ name: 'plain', columns: [{ name: 'text', kind: 'text', primary: false, autoIncrement: false, unique: false, nullable: true }] }];
const equivalent = removeAuditTable(withoutAudit);
equal(JSON.stringify(equivalent), JSON.stringify(withoutAudit), 'missing audit table returns equivalent catalog');
ok(equivalent !== withoutAudit, 'equivalent catalog is a new array');
ok(equivalent[0] !== withoutAudit[0], 'equivalent table is copied');
ok(equivalent[0].columns[0] !== withoutAudit[0].columns[0], 'equivalent column is copied');

equal(installAuditTable([]).length, 1, 'install works on empty catalog');
equal(removeAuditTable([]).length, 0, 'remove works on empty catalog');
const duplicateInput = JSON.stringify(sourceWithAudit);
throwsError(() => installAuditTable(sourceWithAudit), 'existing audit table is rejected');
equal(JSON.stringify(sourceWithAudit), duplicateInput, 'rejected install leaves caller catalog unchanged');

